def icon(name, size=16, cls=''):
    """输出内联 SVG 图标"""
    c = f' {cls}' if cls else ''
    return (f'<svg class="ic{c}" width="{size}" height="{size}" viewBox="0 0 24 24" fill="none" '
            f'stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'
            f'{ICONS[name]}</svg>')
